import{_ as t,o as a,c as o,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/HOST.md","filePath":"manual-zh/HOST.md","lastUpdated":1785684581000}'),d={name:"manual-zh/HOST.md"};function s(n,e,r,P,p,l){return a(),o("div",null,[...e[0]||(e[0]=[c(`<h3 id="_17-14-host" tabindex="-1">17.14 HOST <a class="header-anchor" href="#_17-14-host" aria-label="Permalink to &quot;17.14 HOST&quot;">​</a></h3><p>在下面的语法中，方括号必须包含在命令语法中，并不表示其中的内容是可选的。</p><pre><code>HOST COMMAND=[’command’...]
     TIMELIMIT=secs.
</code></pre><p><code>HOST</code> 在底层操作系统的 shell 中执行一个或多个命令，每个命令作为必需 <code>COMMAND</code> 子命令中的字符串提供。PSPP 在每个独立的 shell 进程中运行命令，并等待其完成后再运行下一个。如果某个命令失败（以非零退出状态退出，或因信号被杀死），则 PSPP 不会运行任何剩余命令。</p><p>PSPP 将 /dev/null 作为 shell 的标准输入。如果进程需要从 stdin 读取，请从文件或设备重定向，或使用管道。</p><p>PSPP 将 shell 的标准输出和标准错误显示为 PSPP 输出。如果不希望如此，请重定向到文件、<code>/dev/null</code> 或其他设备。</p><p>以下示例运行 <code>rsync</code> 将文件从远程服务器复制到本地文件 data.txt，并将 <code>rsync</code> 自身的输出写入 rsync-log.txt。PSPP 显示命令的错误输出（如果有）。如果 <code>rsync</code> 需要提示用户（<em>例如</em> 以获取密码），命令将失败。仅当 <code>rsync</code> 成功时，PSPP 才会运行 <code>sha512sum</code> 命令。</p><pre><code>HOST COMMAND=[&#39;rsync remote:data.txt data.txt &gt; rsync-log.txt&#39;
              &#39;sha512sum -c data.txt.sha512sum].
</code></pre><p>默认情况下，PSPP 会等待这一系列命令完成所需的时间。使用可选的 <code>TIMELIMIT</code> 子命令将执行时间限制为指定的秒数。</p><p>为 mingw 构建的 PSPP 不支持 <code>HOST</code> 的全部功能。</p><p>如果 SAFER（见 <a href="./SET">SET</a>）设置处于活动状态，PSPP 会拒绝此命令。</p>`,11)])])}const m=t(d,[["render",s]]);export{_ as __pageData,m as default};
